"""Migrated validation rules for OPP_MASTER."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _text(value: Any) -> str:
    """Return VRL text-context representation of a field value."""
    return "" if value is None else str(value)


def _number(value: Any) -> Decimal:
    """Return VRL numeric-context representation; empty/missing is zero."""
    if value is None or value == "":
        return Decimal(0)
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _nvl(value: Any, default: Any) -> Any:
    """Implement VRL NVL: only empty/missing/None selects the default."""
    return default if value is None or value == "" else value


def _date_gte(left: Any, right: Any) -> bool:
    """Compare VRL dates, honoring the 00000000 no-value sentinel."""
    left_text = _text(left)
    right_text = _text(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an OPP_MASTER post-write image using migrated VRL rules."""
    errors: list[dict] = []

    def value(column: str) -> Any:
        return record.get(column, "")

    def old_value(column: str) -> Any:
        if event != "UPDATE" or old is None:
            return ""
        return old.get(column, "")

    def add(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {"code": code, "message": message, "severity": severity}
        )

    stat_cd = _text(value("STAT_CD"))
    amount = value("AMT")
    lost_rsn = _text(value("LOST_RSN"))
    close_dt = _text(value("CLOSE_DT"))
    stage_pct = value("STAGE_PCT")

    # OPP-001
    if event in ("INSERT", "UPDATE"):
        if _number(_nvl(amount, 0)) < Decimal(0):
            add("E3001", "Amount negative")

    # OPP-002
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "W" and _number(_nvl(amount, 0)) == Decimal(0):
            add("E3002", "Won opportunity requires amount")

    # OPP-003
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "L" and lost_rsn == "":
            add("E3003", "Lost reason required")

    # OPP-004
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "W" and close_dt == "00000000":
            add("E3004", "Won opportunity requires close date")

    # OPP-005
    if event == "UPDATE":
        if _text(old_value("STAT_CD")) == "W" and stat_cd != "W":
            add("E3005", "Cannot reopen a won opportunity")

    # OPP-006
    if event in ("INSERT", "UPDATE"):
        stage = _number(stage_pct)
        valid_stage = (
            (stat_cd == "P" and stage == Decimal(10))
            or (stat_cd == "Q" and stage == Decimal(25))
            or (stat_cd == "N" and stage == Decimal(60))
            or (stat_cd == "W" and stage == Decimal(100))
            or (stat_cd == "L" and stage == Decimal(0))
        )
        if not valid_stage:
            add("E3006", "Stage percent inconsistent with status")

    # OPP-007
    if event == "INSERT":
        if not (close_dt == "00000000" or _date_gte(close_dt, today)):
            add("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
